// Лаб. 2, п. 2.12. Коннов, СДП-241 ИИ: счётчик в flow context, переживающий podman restart
// (contextStorage настроен на localfilesystem, см. lab2/docs/context-storage.md)
const COUNTER_KEY = "konnovCounter";

let counter = flow.get(COUNTER_KEY);
if (typeof counter !== "number") {
    counter = 0;
}

if (msg.topic === "reset") {
    counter = 0;
} else {
    counter = counter + 1;
}

flow.set(COUNTER_KEY, counter);

msg.payload = {
    action: msg.topic || "increment",
    counter: counter,
    student: "Konnov SDP-241"
};
return msg;
